        lease_expires_at=_string_constraints(_date_time(value["lease_expires_at"]), None, None, None, None),
        lease_id=_decode_LeaseId(value["lease_id"], forward),
        operator=_decode_Operator(value["operator"], forward),
        registry_revision=_decode_PositiveSafeInteger(value["registry_revision"], forward),
        resource_version=_decode_PositiveSafeInteger(value["resource_version"], forward),
        runtime=_decode_Runtime(value["runtime"], forward),
        schema_version=cast(Literal[1], _literal(value["schema_version"], [1])),
        service_id=_decode_ServiceId(value["service_id"], forward),
        session_id=_decode_SessionId(value["session_id"], forward),
