def _decode_RuntimeInstanceSafeInteger(raw: object, forward: bool) -> RuntimeInstanceSafeInteger:
    return _integer(raw, 0, 9007199254740991)

def _decode_RuntimeLabels(raw: object, forward: bool) -> RuntimeLabels:
    value = _object(raw)
    if len(value) > 128: raise ValueError("RuntimeLabels has more than maxProperties")
    for key in value: _string_constraints(_string(key), None, 64, "^[a-z][a-z0-9]*(?:[._-][a-z0-9]+)*$", None)
    known = set([])
    unknown = set(value) - known


    return RuntimeLabels(

        _additional_properties={key: _string_constraints(_string(item), 1, 256, None, None) for key, item in value.items() if key not in known},
    )

