def _pairs(items: list[tuple[str, object]]) -> dict[str, object]:
    result: dict[str, object] = {}
    for key, value in items:
        if key in result: raise ValueError("duplicate JSON key")
        result[key] = value
    return result
def _parse(data: str | bytes) -> object:
    text = data.decode("utf-8", errors="strict") if isinstance(data, bytes) else data
    _validate_json_text(text)
    return json.loads(text, parse_float=Decimal, object_pairs_hook=_pairs, parse_constant=lambda value: (_ for _ in ()).throw(ValueError(value)))
